import{names,makeNetwork,parseGraph,initial,positions,step}from'./model.js';
const $=id=>document.getElementById(id),c=$('gym').getContext('2d'),bc=$('brain').getContext('2d');let net=makeNetwork(),s=initial(),paused=false,speed=1,last=0,scores=[0,0,0,0];const logs=[];
const descriptions=['Push · thorax & front legs','Pull · full exoskeleton','Legs · all six of them','Accessories · tiny arm day'];$('stations').innerHTML=names.map((n,i)=>`<article class="station" id="station${i}"><div class="station-head"><h3>${n}</h3><span class="number">0${i+1}</span></div><small>${descriptions[i]}</small><div class="station-status"><span id="status${i}">AVAILABLE</span><span id="count${i}">0 sets</span></div></article>`).join('');
function event(msg){logs.unshift([s.time,msg]);logs.length=Math.min(logs.length,3);$('events').replaceChildren(...logs.map(([t,m])=>{const p=document.createElement('p'),time=document.createElement('time');time.textContent=format(t);p.append(time,document.createTextNode(m));return p}))}function format(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`}
function poly(points,fill,stroke){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke()}}
function iso(x,y,z=0){return[550+(x-y)*49,315+(x+y)*24-z*52]}
function line(a,b,color='#a8b599',w=5){c.beginPath();c.moveTo(...a);c.lineTo(...b);c.strokeStyle=color;c.lineWidth=w;c.lineCap='round';c.stroke()}
function beam(x,y,z,x2,y2,z2,color='#778772',w=8){line(iso(x,y,z),iso(x2,y2,z2),color,w)}
function box(x,y,z,w,d,h,color='#697961'){const a=iso(x,y,z+h),b=iso(x+w,y,z+h),cc=iso(x+w,y+d,z+h),e=iso(x,y+d,z+h);poly([a,b,cc,e],color);poly([e,cc,iso(x+w,y+d,z),iso(x,y+d,z)],'#34432f');poly([b,cc,iso(x+w,y+d,z),iso(x+w,y,z)],'#46583b')}
function bar(x,y,z,len=1.8){beam(x-len/2,y,z,x+len/2,y,z,'#c6d1bd',5);for(const offset of[-len*.4,len*.4]){const p=iso(x+offset,y,z);c.beginPath();c.ellipse(p[0],p[1],7,19,-.45,0,Math.PI*2);c.fillStyle='#111910';c.fill();c.strokeStyle='#647657';c.lineWidth=3;c.stroke();c.beginPath();c.ellipse(p[0],p[1],2,6,-.45,0,Math.PI*2);c.fillStyle='#c2f970';c.fill()}}
function label(t,x,y){const p=iso(x,y);c.fillStyle='#7c9270';c.font='10px monospace';c.textAlign='center';c.fillText(t,...p)}
function equipment(i){const[x,y]=positions[i],active=s.station===i&&s.phase==='lifting';const lift=active?(Math.sin(s.phaseTime/1.5*Math.PI*2)+1)*.2:0;box(x-1.1,y-.9,-.02,2.2,1.8,.06,i===1?'#766c4d':'#35452e');if(i===0){box(x-.25,y-.6,.5,.5,1.5,.17,'#a8c181');for(const q of[-.8,.8])beam(x+q,y-.55,0,x+q,y-.55,1.5);bar(x,y-.55,1.4+lift)}if(i===1){box(x-.55,y-.8,.045,1.1,1.6,.03,'#a18c62');bar(x,y,.35+lift*2)}if(i===2){for(const a of[-.85,.85])for(const b of[-.6,.6])beam(x+a,y+b,0,x+a,y+b,2.4,'#71856a');for(const a of[-.85,.85])beam(x+a,y-.6,2.4,x+a,y+.6,2.4);beam(x-.85,y-.6,2.4,x+.85,y-.6,2.4);bar(x,y,1.35+lift)}if(i===3){for(const a of[-.8,.8])beam(x+a,y-.35,0,x+a,y-.35,1.1);for(const z of[.45,1]){beam(x-.9,y-.35,z,x+.9,y-.35,z,'#728762',9);for(const a of[-.6,0,.6])bar(x+a,y-.35,z+.13,.42)}}label('0'+(i+1)+' / '+names[i].toUpperCase(),x,y+1.15)}
function fly(){const lifting=s.phase==='lifting',phase=s.phaseTime/1.5*Math.PI*2,bob=lifting?Math.sin(phase)*5:Math.sin(s.time*9)*2,p=iso(s.x,s.y,.5),scale=1+Math.min(.9,(s.mass-1)*.55);c.save();c.translate(p[0],p[1]+bob);c.scale(scale,scale);c.fillStyle='#0004';c.beginPath();c.ellipse(0,31,27,9,0,0,7);c.fill();for(const side of[-1,1]){for(let j=0;j<3;j++){const yy=j*10-8,m=s.phase==='walking'?Math.sin(s.time*9+j)*7:0;line([side*7,yy],[side*(20+j*3),yy+10+m],'#adc67f',3);line([side*(20+j*3),yy+10+m],[side*(29+j*2),yy+20+m],'#809c56',2)}c.beginPath();c.ellipse(side*17,-13,12,25,side*.7,0,7);c.fillStyle='#dcebc950';c.fill();c.strokeStyle='#dcebc980';c.lineWidth=1;c.stroke()}c.fillStyle='#788e43';c.beginPath();c.ellipse(0,11,10,18,0,0,7);c.fill();for(let j=0;j<3;j++)line([-7,8+j*6],[7,8+j*6],'#4f642e',2);c.fillStyle='#b0c875';c.beginPath();c.ellipse(0,-6,11,14,0,0,7);c.fill();c.fillStyle='#94ad58';c.beginPath();c.arc(0,-24,12,0,7);c.fill();for(const a of[-7,7]){c.fillStyle='#ec8d65';c.beginPath();c.ellipse(a,-26,6,8,a*.05,0,7);c.fill();c.fillStyle='#ffdcb7';c.fillRect(a-2,-30,2,3)}line([-4,-34],[-9,-43],'#a8c184',1.5);line([4,-34],[9,-43],'#a8c184',1.5);if(lifting&&s.station===3){for(const a of[-29,29]){const yy=Math.sin(phase)*10;line([a-8,yy],[a+8,yy],'#bbcbaa',3);line([a-8,yy-6],[a-8,yy+6],'#c2f970',5);line([a+8,yy-6],[a+8,yy+6],'#c2f970',5)}}c.restore();c.fillStyle='#c2f970';c.font='10px monospace';c.textAlign='center';c.fillText(s.phase==='resting'?'RECOVERING · z z z':lifting?'REP '+(Math.floor(s.phaseTime/1.5)+1)+' / 8':'ON A MISSION',p[0],p[1]-70*scale)}
function draw(){c.clearRect(0,0,1100,690);const grad=c.createRadialGradient(530,320,30,550,340,600);grad.addColorStop(0,'#34432c');grad.addColorStop(1,'#20291f');c.fillStyle=grad;c.fillRect(0,0,1100,690);poly([iso(-5,-4.5),iso(5,-4.5),iso(5,4.5),iso(-5,4.5)],'#2b3827','#4b5e40');poly([iso(-5,-4.5),iso(5,-4.5),iso(5,-4.5,2.9),iso(-5,-4.5,2.9)],'#35432e');poly([iso(-5,-4.5),iso(-5,4.5),iso(-5,4.5,2.9),iso(-5,-4.5,2.9)],'#303d2b');for(let x=-5;x<=5;x++)beam(x,-4.5,0,x,4.5,0,'#415238',.65);for(let y=-4.5;y<=4.5;y++)beam(-5,y,0,5,y,0,'#415238',.65);beam(-5,-4.5,2.8,5,-4.5,2.8,'#d5ff9f',3);beam(-5,-4.5,2.8,-5,4.5,2.8,'#9fba7c',2);const p=iso(.8,-4.48,1.75);c.save();c.translate(...p);c.transform(1,.49,0,1,0,0);c.fillStyle='#a9c586';c.font='bold 29px monospace';c.textAlign='center';c.fillText('NO FLY DAYS OFF.',0,0);c.restore();[0,2,3,1].forEach(equipment);fly();label('THE 1 mg CLUB',0,5.3);bc.clearRect(0,0,400,140);const pts=Array.from({length:24},(_,i)=>[200+Math.cos(i*2.4)*(40+i*3),70+Math.sin(i*2.4)*(15+i*1.2)]);for(let i=0;i<24;i++){const a=pts[i],b=pts[(i*7+3)%24];bc.strokeStyle='#b6c3a044';bc.beginPath();bc.moveTo(...a);bc.lineTo(...b);bc.stroke()}pts.forEach(([x,y],i)=>{bc.fillStyle=net.activity[i%net.n]>.25?'#94b65f':'#cbd4bd';bc.beginPath();bc.arc(x,y,2+Math.abs(net.activity[i%net.n])*3,0,7);bc.fill()})}
function ui(){$('mass').textContent=s.mass.toFixed(2);$('growth').textContent='+'+((s.mass-1)*100).toFixed(1)+'% since hatching';$('level').textContent=1+Math.floor((s.mass-1)*10);$('energy').value=s.energy;$('fatigue').value=s.fatigue;$('energyText').textContent=Math.round(s.energy)+'%';$('fatigueText').textContent=Math.round(s.fatigue)+'%';$('sets').textContent=s.sets;$('reps').textContent=s.reps;$('clock').textContent='SESSION '+format(s.time);$('decision').textContent=s.phase==='resting'?'Recovery wins.':names[s.station]+' selected';$('thought').textContent=s.phase==='lifting'?'“Light weight. Literally.”':s.phase==='resting'?'“Growth happens between the sets.”':'“Time to get absolutely microscopic.”';names.forEach((_,i)=>{$('station'+i).classList.toggle('active',i===s.station);$('status'+i).textContent=i===s.station?s.phase.toUpperCase():'AVAILABLE';$('count'+i).textContent=s.counts[i]+' sets'});$('feed').disabled=s.time-s.lastBoost<30;$('feed').textContent=s.time-s.lastBoost<30?'✦ Boost cooling down':'✦ Sugar boost'}
function setPaused(value){paused=value;$('pause').textContent=paused?'▶ Resume':'Ⅱ Pause';$('live').textContent=paused?'GYM IS PAUSED':'GYM IS LIVE'}$('pause').onclick=()=>setPaused(!paused);document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(v=>v.classList.toggle('selected',v===b))});$('feed').onclick=()=>{if(s.time-s.lastBoost>=30){s.energy=Math.min(100,s.energy+25);s.lastBoost=s.time;event('Sugar delivered. Buzz restored.');ui()}};$('reset').onclick=()=>{if(confirm('Reset muscle gains and start a new session?')){s=initial();logs.length=0;setPaused(false);event('A new tiny legend enters.');ui()}};for(const id of['about','connect'])$(id).onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>8e6)throw Error('File limit is 8 MB.');const parsed=parseGraph(JSON.parse(await f.text()));net=parsed;$('mode').textContent='IMPORTED';$('neuronCount').textContent=net.n.toLocaleString()+' imported units · illustrative graph';$('importStatus').textContent='Loaded '+net.n+' neurons and '+net.edges.length+' connections. Source is user-declared, not independently verified.';event('Imported graph now drives decisions.')}catch(e){$('importStatus').textContent=e.message}finally{e.target.value=''}};
function frame(t){const dt=Math.min((t-last)/1000,.1);last=t;if(!paused){let remaining=dt*speed;while(remaining>0){const d=Math.min(.05,remaining);scores=step(s,d,net,event);remaining-=d}}draw();ui();requestAnimationFrame(frame)}event('A tiny legend enters the gym.');requestAnimationFrame(frame);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_gym_paused',description:'Pause or resume the visible fly gym session.',inputSchema:{type:'object',properties:{paused:{type:'boolean'}},required:['paused'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.paused!=='boolean')throw Error('paused must be boolean');setPaused(input.paused);return{paused}}})).catch(()=>{})}catch{}}
